import{_ as a,H as e,f as n,i}from"./chunks/framework.BH2BK_3i.js";const E=JSON.parse('{"title":"03 | 原型系统：开源工具自建AI大模型底座","description":"","frontmatter":{},"headers":[{"level":2,"title":"链式调用黏合剂（Langchain）","slug":"链式调用黏合剂-langchain","link":"#链式调用黏合剂-langchain","children":[]},{"level":2,"title":"零代码快速搭建（Flowise）","slug":"零代码快速搭建-flowise","link":"#零代码快速搭建-flowise","children":[]},{"level":2,"title":"领域知识库（Embedding & 向量检索引擎）","slug":"领域知识库-embedding-向量检索引擎","link":"#领域知识库-embedding-向量检索引擎","children":[]},{"level":2,"title":"自主可控 LLM 底座（LocalAI）","slug":"自主可控-llm-底座-localai","link":"#自主可控-llm-底座-localai","children":[]},{"level":2,"title":"更高、更快、更强（Llama）","slug":"更高、更快、更强-llama","link":"#更高、更快、更强-llama","children":[]},{"level":2,"title":"组建你的智能体大军（AutoGPT）","slug":"组建你的智能体大军-autogpt","link":"#组建你的智能体大军-autogpt","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]},{"level":2,"title":"扩展阅读","slug":"扩展阅读","link":"#扩展阅读","children":[]}],"relativePath":"AI大模型系统实战/03｜原型系统：开源工具自建AI大模型底座.md","filePath":"AI大模型系统实战/03｜原型系统：开源工具自建AI大模型底座.md","lastUpdated":1795452834000}'),t={name:"AI大模型系统实战/03｜原型系统：开源工具自建AI大模型底座.md"};function p(l,s,o,h,r,c){return e(),n("div",null,[...s[0]||(s[0]=[i(`<h1 id="_03-原型系统-开源工具自建ai大模型底座" tabindex="-1">03 | 原型系统：开源工具自建AI大模型底座 <a class="header-anchor" href="#_03-原型系统-开源工具自建ai大模型底座" aria-label="Permalink to &quot;03 | 原型系统：开源工具自建AI大模型底座&quot;">​</a></h1><p>你好，我是 Tyler。</p><p>学习了上节课以后，相信你已经摩拳擦掌，想要尽快实现一个自己的大模型应用了。今天，我们就结合实战例子，带你学习怎么通过开源工具组建一个极简应用，让智能体来替你回答工作问题，并让它作为你的专属助理，对你定期进行专题汇报。</p><p>如果你想要直接学习如何使用工具，也可以根据自己的需求，选择目录中感兴趣的内容直接学习。另外需要注意，在这节课的第四部分，我会教你如何搭建一个自主可控的大模型（LLM）底座，所以即使你的工作环境不允许使用 OpenAI API 也没关系。</p><p>今天这节课不会绕弯子，会直接告诉你每个工具的核心价值，让你即学即用。话不多说，我们开始吧！</p><h2 id="链式调用黏合剂-langchain" tabindex="-1">链式调用黏合剂（Langchain） <a class="header-anchor" href="#链式调用黏合剂-langchain" aria-label="Permalink to &quot;链式调用黏合剂（Langchain）&quot;">​</a></h2><p>首先，我们来为你的原型系统搭建一个“调度中心”。这个调度中心将帮助大语言模型（LLM）连接到我们之前学到的各种生态组件，如计划组件、记忆组件和工具组件等等。</p><p>目前最主流的做法是采用链式调用。链式调用可以让你的编码更高效，只需少量代码，就能让用户、LLM 和组件之间进行复杂的互动。</p><p>接下来，我将使用 Langchain，基于 OpenAI 的 LLM 制作一个简易的 ChatGPT。ChatGPT你应该并不陌生，它是一个基于大语言模型的应用程序，可以与人类进行多轮对话。</p><p>为了让大语言模型能够实现与人类友好的多轮对话，我们需要额外引入两个组件。</p><p>第一个是 ConversationBufferMemory，它将帮助 LLM 记录我们的对话过程。</p><p>第二个是 ConversationChain，它会帮我们管理整个会话过程，通过调取 BufferMemory 中的对话信息，让无状态的 LLM 了解我们的对话上下文。</p><p>同时，ConversationChain 还会通过补充一些“提示语”，确保 LLM 知道它在与人类进行交流。</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> langchain.llms </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OpenAI</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> langchain.chains </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ConversationChain</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> langchain.memory </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ConversationBufferMemory</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> os</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">os.environ[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;OPENAI_API_KEY&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;...&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">llm </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OpenAI(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">temperature</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mem </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ConversationBufferMemory()</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Here it is by default set to &quot;AI&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">conversation </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ConversationChain(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">llm</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">llm, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">verbose</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">memory</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mem)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">conversation.predict(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">input</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hi there!&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><ul><li>Entering new ConversationChain chain…Prompt after formatting:The following is a friendly conversation between a human and an AI. The AI is talkativeand provides lots of specific details from its context. If the AI does not know the answer toa question, it truthfully says it does not know.Current conversation:Human: Hi there!AI:Finished chain.Out[1]:&quot; Hi there! It’s nice to meet you. How can I help you today?&quot;</li></ul><p>在这个例子中，我们直接使用了 ConversationChain 的封装。以下是它的核心代码，可以看到整个流程非常简单。ConversationChain 只是对你的对话内容进行了格式化的封装，告诉了LLM 它正在和人类进行对话，并将历史聊天内容提供给 LLM，让 LLM 更好地与用户进行交流。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>from langchain.prompts.prompt import PromptTemplate</span></span>
<span class="line"><span>DEFAULT_TEMPLATE = &quot;&quot;&quot;The following is a friendly conversation between a human an</span></span>
<span class="line"><span>Current conversation:</span></span>
<span class="line"><span>{history}</span></span>
<span class="line"><span>Human: {input}</span></span>
<span class="line"><span>AI:&quot;&quot;&quot;</span></span>
<span class="line"><span>PROMPT = PromptTemplate(input_variables=[&quot;history&quot;, &quot;input&quot;], template=DEFAULT_TE</span></span></code></pre></div><p>你完全也可以根据自己的需求定制自己任务的 Chain。当然，代码示例中可以看出Langchain 对 LLM 生态组件提供了良好的支持，针对常见应用场景也进行了链式封装，这一点做的非常友好。</p><p>比如，SQL Database Chain 就能通过对话来与数据库互动，根据你的需求生成数据报告，这里我也留了一道相关的课后作业。我建议，你在面对这类任务时，优先选择官方的实现，快速完成编码。</p><h2 id="零代码快速搭建-flowise" tabindex="-1">零代码快速搭建（Flowise） <a class="header-anchor" href="#零代码快速搭建-flowise" aria-label="Permalink to &quot;零代码快速搭建（Flowise）&quot;">​</a></h2><p>在学习更高级的用法之前，先给你一个学习加速包，让你“无痛”地进行下面的过程。这个加速包叫做 Flowise，用于零代码搭建 LLM 应用平台。通过使用它，你可以在一分钟内搭建起刚才的应用。</p><p>首先是 Flowise 的安装，在安装完成后通过下面的指令启动 Flowise 服务（推荐用Linux/Mac）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ npm install -g flowise</span></span>
<span class="line"><span>$ npx flowise start --FLOWISE_USERNAME=user --FLOWISE_PASSWORD=1234</span></span></code></pre></div><p>进入浏览器打开 <a href="http://localhost:3000" target="_blank" rel="noreferrer">http://localhost:3000</a>，输入用户名和密码。如果能看到下图中的 Flowise界面，恭喜你已经搭建成功了。现在，我们开始搭建 ChatGPT 的例子。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/03/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/03/1.png" alt=""></a></p><p>这里如下图，在 Chat Models 中找到 ChatOpenAI 组件，拖入我们的应用中，填入刚刚获得的 OpenAI Api Key，它对应代码是后面这样。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>llm = OpenAI(temperature=0)</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/03/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/03/2.png" alt=""></a></p><p>随后，如下图所示，在 Memory 组件中找到 Buffer Memory 组件，拖入到我们的应用中。</p><p>它背后对应的代码是后面这样。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mem = ConversationBufferMemory()</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/03/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/03/3.png" alt=""></a></p><p>最后，我们拖入 LLM Chain 组件，这个动作对应前面 Langchain 这段对代码。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>conversation = ConversationChain(llm=llm, verbose=True, memory=mem)</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/03/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/03/4.png" alt=""></a></p><p>链式调用程序特别适合图形化搭建，接下来，我们点击右上角的会话按钮，就可以和 LLM 对话了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/03/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/03/5.png" alt=""></a></p><p>相信你在刚才的搭建过程中，已经看到了 Flowise 提供的丰富的组件库。这些组件可以帮助你快速搭建原型系统，提升开发效率。如果有兴趣，可以课后研究一下每个组件的用途，以便在未来的开发中灵活运用。</p><p>对于从第二部分开始看的同学，如果你没有 Langchain 的基础知识，建议还是快速通读一下第一部分“链式调用黏合剂”的内容。当然，你也可以根据你的学习习惯，选择先阅读后面的内容，快速建立整体的认识。</p><h2 id="领域知识库-embedding-向量检索引擎" tabindex="-1">领域知识库（Embedding &amp; 向量检索引擎） <a class="header-anchor" href="#领域知识库-embedding-向量检索引擎" aria-label="Permalink to &quot;领域知识库（Embedding &amp; 向量检索引擎）&quot;">​</a></h2><p>在解决了“开发效率”的问题后，我们来谈谈“开发质量”的问题。你有没有观察到一个现象，每隔几天就会看到一个新推出的“领域大模型”。</p><p>这是因为各家机构正在围攻 ChatGPT，希望找到可以难倒它的“领域问题”。随后通过在开发“领域增强大模型”来证明自己的“技术先进性”。</p><p>这类模型有两个标准动作。第一是让 LLM 做好考前“冲刺训练”也就是领域微调，它的训练成本较高，我们会在第四章中讲解这个方法。第二是为模型增加外部记忆，在提示词中引入一些领域知识，帮助模型提升回答质量。</p><p>今天的课程中，我们先使用第二种方法。我将带你制作一个自动问答机器人，它可以帮助你回答其他同事的技术问题，具体制作步骤是这样的。</p><ol><li><p>对团队的技术文档进行切片，生成语义向量（Embedding），存入向量数据库作为外部记忆。</p></li><li><p>根据同事所提问题中的内容，检索向量数据库，获取技术文档的内容片段。</p></li><li><p>把文档片段和同事的问题一并交给大语言模型（LLM），让它理解文档内容，并针对问题形成恰当回答，返回给同事。</p></li></ol><p>我还画了一张流程图，看图一目了然。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/03/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/03/6.png" alt=""></a></p><p>接下来，我们继续使用 Flowise 实现这个项目，你只需要依次加入以下组件。</p><ol><li><p>Folder with Files 组件，负责将相关知识文档上传。</p></li><li><p>Recursive Character Text Splitter 组件，用来给上传的文档内容做断句切片。</p></li><li><p>OpenAI Embeddings 组件负责将断句后的内容切片映射成高维 Embedding。</p></li><li><p>In-Memory Vector Store 组件用来将 Embedding 存入数据库中，供给 LLM 作为外部记忆。</p></li><li><p>Conversational Retrieval QA Chain 组件则会根据问题，获得外部知识，在 LLM 思考形成回答后返回给用户问题答案。</p></li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/03/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/03/7.png" alt=""></a></p><p>通常，你需要将这个对话应用接入到团队所使用的 IM 系统。这里你只需要点击下图的位置，就可以得到 API。对于各种 IM 的 Hook 调用的实现作为你的课后作业。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/03/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/03/8.png" alt=""></a></p><h2 id="自主可控-llm-底座-localai" tabindex="-1">自主可控 LLM 底座（LocalAI） <a class="header-anchor" href="#自主可控-llm-底座-localai" aria-label="Permalink to &quot;自主可控 LLM 底座（LocalAI）&quot;">​</a></h2><p>接下来我们来思考一个问题，如果有一天 OpenAI API 不能用了，该怎么办？</p><p>别担心，我将给你一个安全可控的“底座”，让你没有后顾之忧。这里使用 OpenAI API 的开源替代方案——LocalAI，它可以将唾手可得的开源 LLM，封装成 OpenAI API 相同的接口形式，为你的应用提供服务。</p><p>下面我们开始搭建这个底座，首先执行以下指令，部署 LocalAI 的代码。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git clone https://github.com/go-skynet/LocalAI</span></span>
<span class="line"><span>$ cd LocalAI</span></span></code></pre></div><p>接着，根据以下指令获取 LLM 模型。为了快速验证，这里先下载一个较小的模型。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ wget https://gpt4all.io/models/ggml-gpt4all-j.bin -O models/ggml-gpt4all-j</span></span>
<span class="line"><span>$ cp -rf prompt-templates/ggml-gpt4all-j.tmpl models/</span></span></code></pre></div><p>然后，根据以下指令启动 LocalAI 最新镜像，这个过程会自动加载 models 文件夹中的模型，把它封装为 API 服务。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ docker-compose pull</span></span>
<span class="line"><span>$ docker-compose up -d</span></span></code></pre></div><p>接下来，我们根据以下指令，验证一下模型是否可使用。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ curl http://localhost:8080/v1/models</span></span>
<span class="line"><span>{&quot;object&quot;:&quot;list&quot;,&quot;data&quot;:[{&quot;id&quot;:&quot;ggml-gpt4all-j&quot;,&quot;object&quot;:&quot;model&quot;}]}</span></span></code></pre></div><p>最后，把所有 OpenAI 的组件都换成 LocalAI。这样即使 OpenAI API 不能用，你的项目也能继续稳定运行。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/03/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/03/9.png" alt=""></a></p><h2 id="更高、更快、更强-llama" tabindex="-1">更高、更快、更强（Llama） <a class="header-anchor" href="#更高、更快、更强-llama" aria-label="Permalink to &quot;更高、更快、更强（Llama）&quot;">​</a></h2><p>在使用一段时间后，你会发现机器人的智能水平和 GPT 还有差距。</p><p>其实你可以使用“更大”的模型来提升效果，比如 Meta 开源的 Llama 系列模型。Llama 是Meta AI 公司于 2023 年 2 月发布的大型语言模型系列，Llama-2 已经非常接近 GPT-3.5 的水平，而且可以免费商用。</p><p>首先，如下面的代码所示，我们去 HuggingFace 下载 Llama-2 最新的 ggml 版本。这里我们使用 7B 通用版本来进行演示。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ wget -c &quot;https://huggingface.co/TheBloke/Llama-2-7B-chat-GGML/resolve/main/llam</span></span></code></pre></div><p>下载了模型之后，我们根据以下指令，启动 LocalAI 来快速测试一下模型，确保模型文件没有问题。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ docker-compose up -d</span></span>
<span class="line"><span>$ curl -v  http://localhost:8080/v1/models</span></span>
<span class="line"><span>{&quot;object&quot;:&quot;list&quot;,&quot;data&quot;:[{&quot;id&quot;:&quot;llama-2-7b-chat.ggmlv3.q4_0.bin&quot;,&quot;object&quot;:&quot;model&quot;</span></span></code></pre></div><p>最后，我们回到 Flowise 的界面，将模型名称修改为 llama-2-7b-chat.ggmlv3.q4_0.bin。再次测试聊天机器人，它是不是变得更加聪明了？</p><p>如果需要更大的模型，你可以按需下载。Local AI 已经在底层支持了 llama.cpp，所以 ggml 格式的模型基本都可以适配。你还可以尝试常用的量化方法，但要注意你的 GPU 是否支持。</p><p>当然，如果你想了解各个大模型的具体区别以及如何选择最适合你的量化算法，在后面的课程中我会详细介绍各种模型小型化的方法和原理，让你对它们有更深入的了解，在选择的时候也能做到游刃有余。</p><h2 id="组建你的智能体大军-autogpt" tabindex="-1">组建你的智能体大军（AutoGPT） <a class="header-anchor" href="#组建你的智能体大军-autogpt" aria-label="Permalink to &quot;组建你的智能体大军（AutoGPT）&quot;">​</a></h2><p>接下来，我们用 AutoGPT 建立一个智能体大军。像上节课我们学到的那样，你只要告诉智能体后面这几件事儿，它们就能自己思考、分工、制定计划，完成任务。</p><ul><li><p>目标是什么？</p></li><li><p>有哪些工具可用？</p></li><li><p>有哪些外部记忆可用？</p></li></ul><p>为了描述方便，这里我们给它起个名字，就叫它 MOSS，希望这个名字能让它更智能。</p><p>如果希望 MOSS 帮我们生成“关于 LLM 的每日新闻简报”，就可以这样操作。首先，我们要为MOSS 提供搜索引擎工具，让它可以获取当天的新闻。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>search = SerpAPIWrapper()</span></span>
<span class="line"><span>tools = [</span></span>
<span class="line"><span>   Tool(</span></span>
<span class="line"><span>       name=&quot;search&quot;,</span></span>
<span class="line"><span>       func=search.run,</span></span>
<span class="line"><span>       description=&quot;useful for when you need to answer questions about current e</span></span>
<span class="line"><span>   ),</span></span>
<span class="line"><span>   WriteFileTool(),</span></span>
<span class="line"><span>   ReadFileTool(),</span></span>
<span class="line"><span>]</span></span></code></pre></div><p>接着，我们根据以下代码，将一篇 LLM 综述文章作为外部记忆，辅助它理解相关知识，以便读懂新闻内容。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>embeddings = OpenAIEmbeddings()</span></span>
<span class="line"><span>loader = OnlinePDFLoader(&quot;https://arxiv.org/pdf/2304.13712.pdf&quot;)</span></span>
<span class="line"><span>documents = loader.load()</span></span>
<span class="line"><span>text_splitter = CharacterTextSplitter()</span></span>
<span class="line"><span>docs = text_splitter.split_documents(documents)</span></span>
<span class="line"><span>vectorstore = FAISS.from_documents(docs, embeddings)</span></span></code></pre></div><p>由于 AutoGPT 往往需要由多个不同角色的智能体组成一个团队，协同地完成你的任务。因此，在创造这些智能体时，我们需要给每个智能体一个名字，并且告诉它们负责扮演什么角色。我们的任务目前暂时只需要一个智能体，你需要告诉 MOSS 它有哪些记忆和工具可以使用以及具体的任务是什么即可。</p><p>整个流程就像人类建立团队的过程一样，非常直观，它的代码如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent = AutoGPT.from_llm_and_tools(</span></span>
<span class="line"><span>   ai_name=&quot;MOSS&quot;,</span></span>
<span class="line"><span>   ai_role=&quot;Assistant&quot;,</span></span>
<span class="line"><span>   tools=tools,</span></span>
<span class="line"><span>   llm=ChatOpenAI(temperature=0),</span></span>
<span class="line"><span>   memory=vectorstore.as_retriever(),</span></span>
<span class="line"><span>   chat_history_memory=FileChatMessageHistory(&quot;chat_history.txt&quot;),</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span>agent.run([&quot;write a brief for large language models news today&quot;])</span></span></code></pre></div><p>你可以对比上节课中 ReAct 那张图解释程序的输出，在课后的留言区说说这两者之间有哪些联系。感兴趣的同学课后还可以使用 AgentGPT来体验一下相关概念的商业产品。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/03/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/03/10.png" alt=""></a></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>今天我们学习了如何搭建大语言模型应用，从最底层的模型部署，到上层的 LLM 应用 API，再到最上层的 LLM 应用。涵盖了使用开源工具搭建自用 LLM 应用底座的方方面面。</p><p>这节课的重点是如何使用 Langchain 将你的 LLM 应用组合起来，以及如何快速使用 Flowise零代码平台构建你的应用。另外，我们还学习了如何建立一套自主可控的开源大模型应用底座，使用 LocalAI 基于开源大模型 Llama，来构建你的 LLM API 服务。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/03/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/03/11.png" alt=""></a></p><p>如果你恰好对开源工具更感兴趣，在未来的课程中我给还会给你分享更多好用的开源工具，但是要注意 Langchain 这类开源组件在性能和稳定性以及功能性上都有很大的局限性，不建议直接在工业场景中使用。打个比方吧，将 matlab 用作实验室环境的原型验证那绝对没有问题，但是如果你将它用在生产环境，那结果可想而知。</p><p>最后，我想和你说点题外话。这门课主要面向希望深入理解大型模型系统技术原理，而不满足于仅仅学习简单开源工具的同学。因此，这节课所学的内容，主要用来演示快速验证的“原型系统”如何搭建，如果你想理解这一讲用到的技术背后的知识，彻底了解工业级 AI 系统背后的原理，还是需要踏实学习后面的章节。</p><p>如果你想在这一行有所建树，就不要沉迷在“一日千里”的幻境中，我虽然可以帮你少走弯路，在最短的时间内掌握大部分的开源工具，但是这只是指向月亮的手。最后学完后面课程的所有知识时，你会发现，这些开源工具在工业级大模型系统面前只是“玩具”，技术的深度和广度几乎没有可比性，你已经可以“碾压”只会用这些开源组件的人了。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>通过 Flowise 搭建一个服务并接入你团队的 IM 系统，让它自动按产品经理的需求写临时 SQL查询数据。提示：使用 SQLDatabaseChain。</p><p>恭喜你完成我们第 3 次打卡学习，期待你在留言区和我交流互动。也欢迎你把这节课分享给身边朋友，和 TA 一起学习进步。</p><h2 id="扩展阅读" tabindex="-1">扩展阅读 <a class="header-anchor" href="#扩展阅读" aria-label="Permalink to &quot;扩展阅读&quot;">​</a></h2><p>The Problem With LangChain：<a href="https://minimaxir.com/2023/07/langchain-problem/" target="_blank" rel="noreferrer">https://minimaxir.com/2023/07/langchain-problem/</a></p>`,100)])])}const d=a(t,[["render",p]]);export{E as __pageData,d as default};
